internal static class Program
{
    private const string SourceRelative = "artifacts/identity-benchmark/v2/source-catalog.json";
    private const string V4Root = "artifacts/identity-benchmark/v4/pruning-challenger";
    private const string ProjectionRoot = "artifacts/identity-benchmark/v4/context-projection";
    private const string OutputRelative = "artifacts/identity-benchmark/v4/projected-requests";
    private const int ExpectedCount = 7702;
    private const int ContextLimitTokens = 1_000_000;
    private const int MaxOutputTokens = 768;
    private const string ProjectionVersion = "v4f-b-bounded-source-evidence-projection-v1";
    private static readonly JsonSerializerOptions ReadOptions = new(JsonSerializerDefaults.Web) { PropertyNameCaseInsensitive = true };
    private static readonly JsonSerializerOptions WriteOptions = new(JsonSerializerDefaults.Web) { WriteIndented = true };
    private static readonly Regex ContinuationMarker = new(@"\(\s*(?:cont(?:['’]d)?|continued)\s*\)|\bcontinued\b|tiếp\s+(?:theo|tục)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);
    private static readonly Regex BranchMarker = new(@"\[(?:option|alternative|phương\s+án)\s*[^\]]*\]", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Compiled);

    public static int Main(string[] args)
    {
        try { Run(Path.GetFullPath(args.Length == 1 ? args[0] : Directory.GetCurrentDirectory())); return 0; }
        catch (Exception ex) { Console.Error.WriteLine($"V4F_C_ERROR={ex}"); return 2; }
    }

    private static void Run(string root)
    {
        var sourcePath = Full(root, SourceRelative); var v4ManifestPath = Full(root, V4Root + "/manifest.json"); var shortlistPath = Full(root, V4Root + "/shortlist.json"); var oldRequestPath = Full(root, V4Root + "/request-manifest.json");
        var projectionManifestPath = Full(root, ProjectionRoot + "/manifest.json"); var packetManifestPath = Full(root, ProjectionRoot + "/packet-manifest.json"); var configPath = Full(root, ProjectionRoot + "/projection-config.json");
        using var source = Read(sourcePath); using var v4 = Read(v4ManifestPath); using var shortlist = Read(shortlistPath); using var oldRequests = Read(oldRequestPath); using var projection = Read(projectionManifestPath); using var packets = Read(packetManifestPath); using var config = Read(configPath);
        var failures = VerifyInputs(source, v4, shortlist, oldRequests, projection, packets, sourcePath, v4ManifestPath, shortlistPath, oldRequestPath, projectionManifestPath, packetManifestPath, configPath);
        if (failures.Count != 0) throw new InvalidDataException("BLOCKED_ON_V4F_INPUT_DRIFT: " + string.Join(", ", failures));
        var fingerprint = source.RootElement.GetProperty("catalogFingerprint").GetString()!;
        var sourceDocs = source.RootElement.GetProperty("sourceDocuments").EnumerateArray().ToDictionary(x => x.GetProperty("documentId").GetString()!, x => new SourceDoc(x.GetProperty("documentId").GetString()!, x.GetProperty("sourceSha256").GetString()!, x.GetProperty("sourcePath").GetString()!), StringComparer.Ordinal);
        var nodes = source.RootElement.GetProperty("sourceOccurrences").EnumerateArray().Select(x => new Occurrence(x.GetProperty("nodeId").GetString()!, x.GetProperty("text").GetString()!, x.GetProperty("documentOrder").GetInt32())).ToArray();
        var byDoc = nodes.GroupBy(x => DocumentOf(x.NodeId), StringComparer.Ordinal).ToDictionary(g => g.Key, g => g.OrderBy(x => x.DocumentOrder).ThenBy(x => x.NodeId, StringComparer.Ordinal).ToArray(), StringComparer.Ordinal);
        var candidates = shortlist.RootElement.GetProperty("candidates").EnumerateArray().Select(ReadCandidate).OrderBy(x => x.PairId, StringComparer.Ordinal).ToArray();
        var old = oldRequests.RootElement.GetProperty("requests").EnumerateArray().Select(x => new OldRequest(x.GetProperty("requestId").GetString()!, x.GetProperty("requestBytes").GetInt64())).ToDictionary(x => x.RequestId, StringComparer.Ordinal);
        var frozenPackets = packets.RootElement.GetProperty("packets").EnumerateArray().ToDictionary(x => x.GetProperty("candidateId").GetString()!, x => new FrozenPacket(x.GetProperty("packetBytes").GetInt32(), x.GetProperty("packetSha256").GetString()!, x.GetProperty("packetClass").GetString()!), StringComparer.Ordinal);
        var configHash = Sha256File(configPath); var analyses = new List<Analysis>(ExpectedCount); var packetMismatches = 0; var requestMismatches = 0;
        foreach (var candidate in candidates)
        {
            if (!byDoc.TryGetValue(candidate.DocumentId, out var docNodes)) throw new InvalidDataException("V4F_C_UNKNOWN_DOCUMENT:" + candidate.DocumentId);
            var lookup = docNodes.ToDictionary(x => x.NodeId, StringComparer.Ordinal); if (!lookup.TryGetValue(candidate.Left, out var left) || !lookup.TryGetValue(candidate.Right, out var right)) throw new InvalidDataException("V4F_C_UNKNOWN_OCCURRENCE:" + candidate.PairId);
            var packet = BuildPacket(candidate, left, right, docNodes, sourceDocs[candidate.DocumentId], fingerprint, configHash); var packetBytes = JsonSerializer.SerializeToUtf8Bytes(packet, WriteOptions); var packetHash = Hash(packetBytes);
            if (!frozenPackets.TryGetValue(candidate.PairId, out var frozenPacket) || frozenPacket.PacketBytes != packetBytes.Length || frozenPacket.PacketSha256 != packetHash) { packetMismatches++; continue; }
            if (!old.TryGetValue(candidate.PairId, out var oldRequest)) throw new InvalidDataException("V4F_C_OLD_REQUEST_MISSING:" + candidate.PairId);
            using var packetDocument = JsonDocument.Parse(packetBytes);
            var built = HdsaCanonicalProjectedPairVerifierRequestBuilder.Build(packetDocument.RootElement, "qwen/qwen3.7-flash", "OpenRouter", MaxOutputTokens);
            var rebuilt = HdsaCanonicalProjectedPairVerifierRequestBuilder.Build(packetDocument.RootElement, "qwen/qwen3.7-flash", "OpenRouter", MaxOutputTokens);
            if (!built.Utf8Bytes.SequenceEqual(rebuilt.Utf8Bytes) || built.Sha256 != rebuilt.Sha256) { requestMismatches++; continue; }
            var requestRoot = JsonDocument.Parse(built.Utf8Bytes).RootElement; var parts = BuildParts(requestRoot, built.Utf8Bytes.Length);
            analyses.Add(new(candidate.PairId, candidate.DocumentId, oldRequest.RequestBytes, packetBytes.Length, packetHash, built.Utf8Bytes.Length, built.Sha256, packet, parts));
        }
        if (packetMismatches != 0 || requestMismatches != 0 || analyses.Count != ExpectedCount) throw new InvalidDataException($"V4F_C_RECONSTRUCTION_FAILED packets={packetMismatches} requests={requestMismatches} accepted={analyses.Count}");
        var output = Full(root, OutputRelative); Directory.CreateDirectory(output);
        var packetManifestSha = Sha256File(packetManifestPath); var builderPath = Full(root, "src/DocxHeaderExtractor.Core/Models/HdsaCanonicalProjectedPairVerifierRequestBuilder.cs");
        var perDoc = analyses.GroupBy(x => x.DocumentId, StringComparer.Ordinal).OrderBy(x => x.Key, StringComparer.Ordinal).Select(g => new { documentId = g.Key, requestCount = g.Count(), old = Distribution(g.Select(x => (long)x.OldBytes)), projected = Distribution(g.Select(x => (long)x.ProjectedBytes)), oldTotalBytes = g.Sum(x => (long)x.OldBytes), projectedTotalBytes = g.Sum(x => (long)x.ProjectedBytes), reductionPercentage = Ratio(g.Sum(x => (long)x.OldBytes - x.ProjectedBytes), g.Sum(x => (long)x.OldBytes)) }).ToArray();
        var oldTotal = analyses.Sum(x => (long)x.OldBytes); var projectedTotal = analyses.Sum(x => (long)x.ProjectedBytes); var payload = Payload(analyses); var context = Context(analyses); var requestEntries = analyses.Select(x => new { requestId = x.CandidateId, candidateId = x.CandidateId, packetId = "packet:" + x.CandidateId, documentId = x.DocumentId, packetSha256 = x.PacketSha256, exactByteLength = x.ProjectedBytes, requestSha256 = x.RequestSha256, builderVersion = HdsaCanonicalProjectedPairVerifierRequestBuilder.Version, builderHash = Sha256File(builderPath), model = "qwen/qwen3.7-flash", provider = "OpenRouter", configurationHash = Sha256Text("OpenRouter|qwen/qwen3.7-flash|768|hdsa-global-identity-retrieve-verify-v1") }).ToArray();
        Write(output + "/request-contract.json", new { artifactKind = "a99_identity_benchmark_v4f_c_projected_request_contract", schemaVersion = "a99-v4f-c-request-contract-v1", builderVersion = HdsaCanonicalProjectedPairVerifierRequestBuilder.Version, decisionContract = "hdsa-global-identity-retrieve-verify-v1", decisionOptions = new[] { "CONTINUATION_OF", "SAME_SEMANTIC_REPEAT", "DISTINCT", "UNRESOLVED" }, responseSchema = HdsaGlobalIdentityRetrieveVerifyContract.VerificationSchema(), evidenceAdditions = "NONE; consumes frozen V4F-B packet reconstruction only", fullDocumentContext = false, goldAccess = false, providerExecution = false });
        Write(output + "/request-manifest.json", new { artifactKind = "a99_identity_benchmark_v4f_c_request_manifest", schemaVersion = "a99-v4f-c-request-manifest-v1", requestCount = analyses.Count, packetManifestSha256 = packetManifestSha, packetManifestConsumedAsFrozen = true, packetBodiesPersisted = false, exactBytesPersisted = false, exactBytesDeterministicallyReconstructible = true, canonicalOrdering = "candidateId ASC", requests = requestEntries });
        Write(output + "/size-distribution.json", new { artifactKind = "a99_identity_benchmark_v4f_c_size_distribution", schemaVersion = "a99-v4f-c-size-distribution-v1", oldRequestBytes = Distribution(analyses.Select(x => (long)x.OldBytes)), projectedRequestBytes = Distribution(analyses.Select(x => (long)x.ProjectedBytes)), oldEstimatedTokens = Distribution(analyses.Select(x => (long)Estimate(x.OldBytes))), projectedEstimatedTokens = Distribution(analyses.Select(x => (long)Estimate(x.ProjectedBytes))), comparison = new { oldTotalBytes = oldTotal, projectedTotalBytes = projectedTotal, reductionBytes = oldTotal - projectedTotal, reductionPercentage = Ratio(oldTotal - projectedTotal, oldTotal), compressionRatio = oldTotal / (double)projectedTotal }, perDocument = perDoc });
        Write(output + "/payload-decomposition.json", payload);
        Write(output + "/context-limit-analysis.json", context);
        Write(output + "/reconstruction-report.json", new { artifactKind = "a99_identity_benchmark_v4f_c_reconstruction_report", schemaVersion = "a99-v4f-c-reconstruction-report-v1", packetReconstruction = "PASS", projectedRequestReconstruction = "PASS", packetShaMismatches = packetMismatches, requestShaMismatches = requestMismatches, accepted = analyses.Count, expected = ExpectedCount, oldRequestCandidateIdentityPreserved = true, fullDocumentContextBytes = 0, dryRunTransportCalls = 0, builderVersion = HdsaCanonicalProjectedPairVerifierRequestBuilder.Version, builderHash = Sha256File(builderPath) });
        Write(output + "/firewall.json", new { artifactKind = "a99_identity_benchmark_v4f_c_firewall", schemaVersion = "a99-v4f-c-firewall-v1", goldReadCount = 0, v4ebEvaluationReadCount = 0, providerCalls = 0, modelCalls = 0, candidateUniverseChanged = false, rankingChanged = false, evidenceRepresentationChanged = true, requestPromptChanged = false, evidenceAdded = false, fullDocumentContextIncluded = false, packetBodiesPersisted = false, exactReconstruction = "PASS", dryRunTransportCalls = 0, tamperedPacketFailsClosed = true, tamperedManifestFailsClosed = true, candidateOrderCanonicalized = true });
        Write(output + "/manifest.json", new { artifactKind = "a99_identity_benchmark_v4f_c_manifest", schemaVersion = "a99-v4f-c-manifest-v1", status = "READY_FOR_PROJECTED_VERIFIER_EXPERIMENT_DESIGN", developmentStatus = "DEV_EXPOSED_CHALLENGER", independentGeneralizationClaim = false, parent = "V4F-B@6133127", candidateUniverseChanged = false, rankingChanged = false, evidenceRepresentationChanged = true, providerExecuted = false, candidateCount = candidates.Length, projectedRequestCount = analyses.Count, sourceCatalogSha256 = Sha256File(sourcePath), sourceCatalogFingerprint = fingerprint, shortlistSha256 = Sha256File(shortlistPath), v4eRequestManifestSha256 = Sha256File(oldRequestPath), v4fBPacketManifestSha256 = packetManifestSha, projectionConfigSha256 = configHash, projectedRequestBuilderVersion = HdsaCanonicalProjectedPairVerifierRequestBuilder.Version, projectedRequestBuilderHash = Sha256File(builderPath), oldRequestTotalBytes = oldTotal, oldRequestEstimatedTokens = analyses.Sum(x => (long)Estimate(x.OldBytes)), projectedRequestTotalBytes = projectedTotal, projectedRequestEstimatedTokens = analyses.Sum(x => (long)Estimate(x.ProjectedBytes)), requestCountPreserved = true, exactBytesPersisted = false, exactBytesDeterministicallyReconstructible = true, goldReadCount = 0, v4ebEvaluationReadCount = 0, providerCalls = 0, modelCalls = 0, packetClasses = analyses.GroupBy(x => PacketClass(x.Packet), StringComparer.Ordinal).OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => new { packetClass = x.Key, count = x.Count() }).ToArray(), nextGate = "READY_FOR_PROJECTED_VERIFIER_EXPERIMENT_DESIGN" });
        File.WriteAllText(output + "/report.md", BuildReport(analyses, oldTotal, projectedTotal, payload, context, configHash), new UTF8Encoding(false));
        Console.WriteLine($"V4F_C_COMPLETE candidates={candidates.Length} projectedRequests={analyses.Count} projectedBytes={projectedTotal} reduction={Ratio(oldTotal - projectedTotal, oldTotal):P4}");
    }

    private static Packet BuildPacket(Candidate c, Occurrence left, Occurrence right, Occurrence[] nodes, SourceDoc source, string fingerprint, string configHash)
    {
        var li = Array.IndexOf(nodes, left); var ri = Array.IndexOf(nodes, right); var ordered = li <= ri ? (li, ri) : (ri, li); var allBetween = nodes.Skip(ordered.Item1 + 1).Take(Math.Max(0, ordered.Item2 - ordered.Item1 - 1)).ToArray(); var between = Bounded(allBetween, 8).Select(x => Core(x, source)).ToArray();
        var local = new LocalContext(Neighbors(nodes, li, -1, 2, source), Neighbors(nodes, li, 1, 2, source), Neighbors(nodes, ri, -1, 2, source), Neighbors(nodes, ri, 1, 2, source), between, allBetween.Length > between.Length, allBetween.Length);
        var structural = new StructuralContext(new[] { Container(left.NodeId), Container(right.NodeId) }.Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray(), StructuralPeers(nodes, li, ri));
        var relational = new RelationalFacts(Math.Abs(left.DocumentOrder - right.DocumentOrder), Normalize(left.Text) == Normalize(right.Text), Markers(left.Text), Markers(right.Text), Branches(left.Text), Branches(right.Text), c.Reasons.Order(StringComparer.Ordinal).ToArray());
        var availability = new EvidenceAvailability("AVAILABLE", "AVAILABLE", "AVAILABLE", "UNAVAILABLE", "UNAVAILABLE", "UNAVAILABLE", "UNAVAILABLE", allBetween.Length > 0 ? "AVAILABLE" : "UNAVAILABLE");
        return new("a99_identity_benchmark_v4f_b_pair_evidence_packet", "v4f-b-pair-evidence-packet-v1", c.PairId, c.DocumentId, new[] { Core(left, source), Core(right, source) }, local, structural, relational, availability, new[] { new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "source occurrence text/order/container", "AVAILABLE"), new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "bounded context selected by source order", "AVAILABLE"), new EvidenceAuthority("FROZEN_SOURCE_CATALOG", "source path extension", "AVAILABLE") }, new[] { "numbering", "scope", "layout", "visual" }, ProjectionVersion, fingerprint, configHash);
    }
    private static PairOccurrence Core(Occurrence x, SourceDoc s) => new(x.NodeId, x.Text, Normalize(x.Text), x.DocumentOrder, Path.GetExtension(s.SourcePath).Equals(".pdf", StringComparison.OrdinalIgnoreCase) ? "PDF" : "SOURCE_PACKET", Container(x.NodeId));
    private static IReadOnlyList<PairOccurrence> Neighbors(IReadOnlyList<Occurrence> all, int index, int direction, int count, SourceDoc source) => (direction < 0 ? all.Take(index).TakeLast(count) : all.Skip(index + 1).Take(count)).Select(x => Core(x, source)).ToArray();
    private static IReadOnlyList<Occurrence> Bounded(IReadOnlyList<Occurrence> all, int max) => all.Count <= max ? all : all.Take(max / 2).Concat(all.TakeLast(max - max / 2)).ToArray();
    private static IReadOnlyList<StructuralPeer> StructuralPeers(IReadOnlyList<Occurrence> nodes, int left, int right) => nodes.Select((x, i) => (x, i)).Where(x => x.i == left || x.i == right).SelectMany(anchor => nodes.Select((x, i) => (x, i)).Where(x => x.i != left && x.i != right && Container(x.x.NodeId) == Container(anchor.x.NodeId)).OrderBy(x => Math.Abs(x.i - anchor.i)).ThenBy(x => x.x.NodeId, StringComparer.Ordinal).Take(4)).Select(x => new StructuralPeer(x.x.NodeId, x.x.DocumentOrder, Container(x.x.NodeId))).DistinctBy(x => x.SourceOccurrenceId).OrderBy(x => x.DocumentOrder).ThenBy(x => x.SourceOccurrenceId, StringComparer.Ordinal).Take(4).ToArray();
    private static string[] Markers(string text) => ContinuationMarker.Matches(text).Select(x => x.Value).Order(StringComparer.Ordinal).ToArray();
    private static string[] Branches(string text) => BranchMarker.Matches(text).Select(x => x.Value).Order(StringComparer.Ordinal).ToArray();
    private static string Normalize(string text) => string.Join(' ', text.Normalize(System.Text.NormalizationForm.FormKC).Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
    private static string Container(string id) => (id.Split(':', 2).ElementAtOrDefault(1) ?? id).Split('/').FirstOrDefault() ?? string.Empty;
    private static string DocumentOf(string id) => id.Split(':', 2)[0];
    private static string PacketClass(Packet p) => p.StructuralContext.StructuralPeers.Count > 0 ? "STRUCTURALLY_PARTIAL" : p.LocalContext.Intervening.Count > 0 || p.LocalContext.PreviousOfLeft.Count > 0 || p.LocalContext.NextOfRight.Count > 0 ? "LOCAL_ONLY" : "PAIR_ONLY";
    private static Parts BuildParts(JsonElement root, int total) { long Sum(string name) => Encoding.UTF8.GetBytes(root.GetProperty(name).GetRawText()).Length; var pair = Encoding.UTF8.GetBytes(root.GetProperty("pairEvidencePacket").GetProperty("pairCore").GetRawText()).Length; var local = Encoding.UTF8.GetBytes(root.GetProperty("pairEvidencePacket").GetProperty("localContext").GetRawText()).Length; var structural = Encoding.UTF8.GetBytes(root.GetProperty("pairEvidencePacket").GetProperty("structuralContext").GetRawText()).Length; var relational = Encoding.UTF8.GetBytes(root.GetProperty("pairEvidencePacket").GetProperty("relationalFacts").GetRawText()).Length; var staticInstruction = Sum("systemContract"); var schema = Sum("responseSchema"); var envelope = Sum("modelConfiguration") + Sum("decisionOptions"); return new(staticInstruction, pair, local, structural, relational, schema, envelope, total - staticInstruction - pair - local - structural - relational - schema - envelope); }
    private static object Payload(IReadOnlyList<Analysis> a) { long s = 0, p = 0, l = 0, st = 0, r = 0, schema = 0, env = 0; foreach (var x in a) { s += x.Parts.StaticInstruction; p += x.Parts.PairCore; l += x.Parts.LocalContext; st += x.Parts.StructuralContext; r += x.Parts.RelationalFacts; schema += x.Parts.ResponseSchema; env += x.Parts.ProviderEnvelope; } var total = a.Sum(x => (long)x.ProjectedBytes); var other = total - s - p - l - st - r - schema - env; return new { artifactKind = "a99_identity_benchmark_v4f_c_payload_decomposition", schemaVersion = "a99-v4f-c-payload-decomposition-v1", totals = new { totalBytes = total, staticInstructionBytes = s, pairCoreBytes = p, localContextBytes = l, structuralContextBytes = st, relationalSourceFactsBytes = r, responseSchemaBytes = schema, providerEnvelopeBytes = env, otherBytes = other, fullDocumentContextBytes = 0L, exactSum = s + p + l + st + r + schema + env + other == total }, percentages = new { staticInstruction = Ratio(s, total), pairCore = Ratio(p, total), localContext = Ratio(l, total), structuralContext = Ratio(st, total), relationalSourceFacts = Ratio(r, total), responseSchema = Ratio(schema, total), providerEnvelope = Ratio(env, total), other = Ratio(other, total), fullDocumentContext = 0d } }; }
    private static object Context(IReadOnlyList<Analysis> a) { var values = a.Select(x => (long)Estimate(x.ProjectedBytes)).ToArray(); var safe = values.Count(x => x < ContextLimitTokens * .9); var near = values.Count(x => x >= ContextLimitTokens * .9 && x <= ContextLimitTokens); var exceeds = values.Count(x => x > ContextLimitTokens); return new { artifactKind = "a99_identity_benchmark_v4f_c_context_limit_analysis", schemaVersion = "a99-v4f-c-context-limit-analysis-v1", configuredContextLimitTokens = ContextLimitTokens, providerVerifiedContextLimitTokens = (int?)null, providerVerified = false, estimatedInputTokens = Distribution(values), classification = new { safe = new { count = safe, percentage = Ratio(safe, values.Length) }, near = new { count = near, percentage = Ratio(near, values.Length) }, exceeds = new { count = exceeds, percentage = Ratio(exceeds, values.Length) } }, status = exceeds == 0 ? "WITHIN_CONFIGURED_LIMIT_NOT_PROVIDER_VERIFIED" : "EXCEEDS_CONFIGURED_LIMIT" }; }
    private static object Distribution(IEnumerable<long> values) { var v = values.OrderBy(x => x).ToArray(); return new { count = v.Length, min = v.DefaultIfEmpty(0).Min(), p50 = Percentile(v, .5), p75 = Percentile(v, .75), p90 = Percentile(v, .9), p95 = Percentile(v, .95), p99 = Percentile(v, .99), max = v.DefaultIfEmpty(0).Max(), mean = v.Length == 0 ? 0 : Math.Round(v.Average(), 3), total = v.Sum() }; }
    private static long Percentile(long[] v, double p) => v.Length == 0 ? 0 : v[Math.Min(v.Length - 1, (int)Math.Floor(p * (v.Length - 1)))];
    private static int Estimate(long b) => checked((int)((b + 3) / 4));
    private static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    private static string Sha256File(string p) => Hash(File.ReadAllBytes(p));
    private static string Sha256Text(string s) => Hash(Encoding.UTF8.GetBytes(s));
    private static Candidate ReadCandidate(JsonElement x) => new(x.GetProperty("pairId").GetString()!, x.GetProperty("documentId").GetString()!, x.GetProperty("left").GetString()!, x.GetProperty("right").GetString()!, x.TryGetProperty("reasons", out var r) ? r.EnumerateArray().Select(y => y.GetString()!).ToArray() : []);
    private static string Full(string root, string path) => Path.Combine(root, path.Replace('/', Path.DirectorySeparatorChar));
    private static JsonDocument Read(string p) => JsonDocument.Parse(File.ReadAllText(p));
    private static void Write(string p, object value) => File.WriteAllText(p, JsonSerializer.Serialize(value, WriteOptions) + Environment.NewLine, new UTF8Encoding(false));
    private static double Ratio(long n, long d) => d == 0 ? 0 : Math.Round(n / (double)d, 8);
    private static string BuildReport(IReadOnlyList<Analysis> a, long oldTotal, long newTotal, object payload, object context, string configHash) => $"# A99 V4F-C — projected identity verifier request freeze\n\nStatus: **READY_FOR_PROJECTED_VERIFIER_EXPERIMENT_DESIGN**\n\nThis offline freeze consumes V4F-B packet identities as frozen hash artifacts and reconstructs them deterministically from the same source catalog, candidate IDs and projection config. No provider/model call, Gold read, or V4E-B evaluation read occurred.\n\n## Checkpoint\n\n- Parent: `V4F-B@6133127`; candidates: **{a.Count:N0} → {a.Count:N0}**.\n- Old context: **{oldTotal:N0} bytes** / **{a.Sum(x => (long)Estimate(x.OldBytes)):N0} estimated tokens**.\n- Projected requests: **{newTotal:N0} bytes** / **{a.Sum(x => (long)Estimate(x.ProjectedBytes)):N0} estimated tokens**.\n- Reduction: **{oldTotal - newTotal:N0} bytes ({Ratio(oldTotal - newTotal, oldTotal):P4})**; compression **{oldTotal / (double)newTotal:N2}x**.\n- Projection config SHA: `{configHash}`; packet bodies and request bodies persisted: `false`.\n\n## Contract\n\nThe decision contract remains `hdsa-global-identity-retrieve-verify-v1` with the unchanged four relation options and verification schema. The only semantic input change is replacing full-document context with the frozen bounded packet. No new evidence was added. Full-document context in the projected request is **0 bytes**.\n\n## Payload and context\n\nSee `payload-decomposition.json` for exact category sums and `context-limit-analysis.json` for configured-limit classification. The latter is not provider-verified.\n\n## Firewall\n\n`GoldReadCount=0`; `V4EBEvaluationReadCount=0`; `ProviderCalls=0`; `ModelCalls=0`; candidate universe unchanged; ranking unchanged; dry-run transport calls `0`; packet/request reconstruction `PASS`.\n\n## Gate\n\n**READY_FOR_PROJECTED_VERIFIER_EXPERIMENT_DESIGN**. Next step is to design a small stratified old-vs-projected verifier experiment; do not execute provider calls from this checkpoint.\n";

    private static List<string> VerifyInputs(JsonDocument source, JsonDocument v4, JsonDocument shortlist, JsonDocument oldRequests, JsonDocument projection, JsonDocument packets, params string[] paths)
    { var f = new List<string>(); void C(bool ok, string n) { if (!ok) f.Add(n); } var m = v4.RootElement; var p = projection.RootElement; var packetManifestHash = Sha256File(paths[5]); C(m.GetProperty("shortlistedCount").GetInt32() == ExpectedCount, "v4e.shortlist"); C(m.GetProperty("requestCount").GetInt32() == ExpectedCount, "v4e.request.count"); C(shortlist.RootElement.GetProperty("candidates").GetArrayLength() == ExpectedCount, "shortlist.count"); C(oldRequests.RootElement.GetProperty("requestCount").GetInt32() == ExpectedCount, "old.request.count"); C(p.GetProperty("candidateCount").GetInt32() == ExpectedCount && p.GetProperty("projectedPacketCount").GetInt32() == ExpectedCount, "v4fB.count"); C(packets.RootElement.GetProperty("packetCount").GetInt32() == ExpectedCount, "packet.manifest.count"); C(Sha256File(paths[2]) == m.GetProperty("shortlistSha256").GetString(), "shortlist.sha"); C(Sha256File(paths[3]) == m.GetProperty("requestManifestSha256").GetString(), "old.request.sha"); C(Sha256File(paths[0]) == m.GetProperty("sourceCatalogSha256").GetString(), "source.sha"); C(Sha256File(paths[0]) == p.GetProperty("sourceCatalogSha256").GetString(), "projection.source.sha"); C(packets.RootElement.GetProperty("projectionConfigSha256").GetString() == p.GetProperty("projectionConfigSha256").GetString(), "packet.config.sha"); C(source.RootElement.GetProperty("goldDerivedInput").GetBoolean() == false, "source.gold"); C(oldRequests.RootElement.GetProperty("goldDerivedInput").GetBoolean() == false, "old.request.gold"); C(p.GetProperty("providerCalls").GetInt32() == 0 && p.GetProperty("goldReadCount").GetInt32() == 0, "projection.firewall"); C(packetManifestHash.Length == 64, "packet.manifest.hash"); return f; }

    private sealed record SourceDoc(string DocumentId, string SourceSha256, string SourcePath);
    private sealed record Occurrence(string NodeId, string Text, int DocumentOrder);
